package co.com.empresa.domain.typecategory;import co.com.empresa.commons.exception.DomainException;import co.com.empresa.domain.constants.DomainErrors;import org.jeasy.random.EasyRandom;import org.junit.jupiter.api.BeforeEach;import org.junit.jupiter.api.DisplayName;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;class TypeCategoryTest {    private EasyRandom easyRandom;    @BeforeEach    void setUp() {        easyRandom = new EasyRandom();    }    @Test    @DisplayName("Should validate successfully when all required fields are present")    void validate_Success() {        TypeCategory category = easyRandom.nextObject(TypeCategory.class);        category.setName("Valid Category");        category.setCode("VALID_CAT");        assertDoesNotThrow(category::validate);    }    @Test    @DisplayName("Should throw exception when name is blank")    void validate_BlankName_ThrowsException() {        TypeCategory category = easyRandom.nextObject(TypeCategory.class);        category.setName("");        DomainException exception = assertThrows(DomainException.class, category::validate);        assertEquals(DomainErrors.ERROR_TYPE_CATEGORY_NAME_EMPTY, exception.getMessage());    }    @Test    @DisplayName("Should throw exception when code is null")    void validate_NullCode_ThrowsException() {        TypeCategory category = easyRandom.nextObject(TypeCategory.class);        category.setCode(null);        DomainException exception = assertThrows(DomainException.class, category::validate);        assertEquals(DomainErrors.ERROR_TYPE_CATEGORY_CODE_EMPTY, exception.getMessage());    }}